"""Fonctions natives de K+ (spécification §8).

Chaque fonction reçoit l'interpréteur et la liste des arguments déjà évalués.
"""

import math
import re
from decimal import ROUND_HALF_UP, Decimal, localcontext

from .erreurs import ErreurType, ErreurValeur, SignalQuitter
from .operations import verifier_decimal
from .valeurs import (
    FonctionNative, decrire_type, est_nombre, nom_type, representer,
)

MOTIF_ENTIER = re.compile(r"\s*[+-]?[0-9]+\s*")
MOTIF_DECIMAL = re.compile(r"\s*[+-]?[0-9]+(\.[0-9]+)?([eE][+-]?[0-9]+)?\s*")


def _exiger_nombre(nom, v, position="l'argument"):
    if not est_nombre(v):
        raise ErreurType(f"{nom}() attend un nombre comme {position}, "
                         f"pas {decrire_type(v)}")


def afficher(interp, args):
    interp.sortie.write(" ".join(representer(a) for a in args) + "\n")
    interp.sortie.flush()
    return None


def demander(interp, args):
    invite = ""
    if args:
        invite = args[0]
        if type(invite) is not str:
            raise ErreurType(f"demander() attend un texte comme invite, "
                             f"pas {decrire_type(invite)}")
    try:
        return interp.lire_ligne(invite)
    except EOFError:
        return None


def texte(interp, args):
    return representer(args[0])


def entier(interp, args):
    v = args[0]
    if type(v) is int:
        return v
    if type(v) is float:
        return int(v)                       # tronque vers zéro
    if type(v) is str:
        if MOTIF_ENTIER.fullmatch(v):
            return int(v.strip())
        conseil = None
        if MOTIF_DECIMAL.fullmatch(v):
            conseil = "pour un nombre à virgule, utilisez decimal(...) puis entier(...)"
        raise ErreurValeur(f"impossible de convertir le texte \"{v}\" en entier",
                           conseil=conseil)
    raise ErreurType(f"impossible de convertir {decrire_type(v)} en entier")


def decimal(interp, args):
    v = args[0]
    if type(v) is float:
        return v
    if type(v) is int:
        try:
            return float(v)
        except OverflowError:
            raise ErreurValeur("entier trop grand pour être converti en décimal") from None
    if type(v) is str:
        if MOTIF_DECIMAL.fullmatch(v):
            r = float(v.strip())
            if math.isinf(r):
                raise ErreurValeur(f"le nombre \"{v}\" est trop grand")
            return r
        conseil = None
        if re.fullmatch(r"\s*[+-]?[0-9]+,[0-9]+\s*", v):
            conseil = "le séparateur décimal est le point : 3.5"
        raise ErreurValeur(f"impossible de convertir le texte \"{v}\" en décimal",
                           conseil=conseil)
    raise ErreurType(f"impossible de convertir {decrire_type(v)} en décimal")


def type_(interp, args):
    return nom_type(args[0])


def longueur(interp, args):
    v = args[0]
    if type(v) in (str, list):
        return len(v)
    raise ErreurType(f"longueur() attend un texte ou une liste, pas {decrire_type(v)}")


def ajouter(interp, args):
    liste, valeur = args
    if type(liste) is not list:
        raise ErreurType(f"ajouter() attend une liste comme premier argument, "
                         f"pas {decrire_type(liste)}")
    liste.append(valeur)
    return None


def absolu(interp, args):
    _exiger_nombre("absolu", args[0])
    return abs(args[0])


def racine(interp, args):
    x = args[0]
    _exiger_nombre("racine", x)
    if x < 0:
        raise ErreurValeur("racine() d'un nombre négatif n'existe pas dans les "
                           "nombres réels")
    try:
        return math.sqrt(x)
    except OverflowError:
        return float(math.isqrt(x))


def _arrondir_decimal(x, chiffres):
    """Arrondi « au plus proche, les demis en s'éloignant de zéro »."""
    with localcontext() as ctx:
        ctx.prec = 1000
        d = Decimal(repr(x)) if type(x) is float else Decimal(x)
        return d.quantize(Decimal(1).scaleb(-chiffres), rounding=ROUND_HALF_UP)


def arrondir(interp, args):
    x = args[0]
    _exiger_nombre("arrondir", x, "premier argument")
    if len(args) == 1:
        if type(x) is int:
            return x
        return int(_arrondir_decimal(x, 0))
    n = args[1]
    if type(n) is not int:
        raise ErreurType(f"arrondir() attend un entier comme nombre de chiffres, "
                         f"pas {decrire_type(n)}")
    if n < 0:
        raise ErreurValeur("le nombre de chiffres après la virgule doit être ≥ 0")
    try:
        if n > 400:                         # au-delà de la précision d'un décimal
            return verifier_decimal(float(x))
        return verifier_decimal(float(_arrondir_decimal(x, n)))
    except OverflowError:
        raise ErreurValeur("nombre trop grand pour être converti en décimal") from None


def quitter(interp, args):
    raise SignalQuitter(0)


# nom -> (nombre minimal d'arguments, nombre maximal ou None, fonction)
NATIVES = {
    "afficher": (0, None, afficher),
    "demander": (0, 1, demander),
    "texte": (1, 1, texte),
    "entier": (1, 1, entier),
    "decimal": (1, 1, decimal),
    "décimal": (1, 1, decimal),
    "type": (1, 1, type_),
    "longueur": (1, 1, longueur),
    "ajouter": (2, 2, ajouter),
    "absolu": (1, 1, absolu),
    "racine": (1, 1, racine),
    "arrondir": (1, 2, arrondir),
    "quitter": (0, 0, quitter),
}

NOMS_NATIFS = frozenset(NATIVES)


def installer(environnement):
    for nom, (mini, maxi, fonction) in NATIVES.items():
        environnement.definir_native(nom, FonctionNative(nom, mini, maxi, fonction))

fichiers.kplus/operations.py:
"""Opérateurs de K+ : arithmétique, comparaisons, accès par indice.

Règles : spécification §5. Les erreurs sont levées sans position ;
l'interpréteur y ajoute la ligne et la colonne du nœud concerné.
"""

import math

from .erreurs import ErreurDivisionParZero, ErreurIndex, ErreurType, ErreurValeur
from .valeurs import decrire_type, egal, est_nombre

# Au-delà, « a ^ b » entre entiers est refusé (protection mémoire/temps).
LIMITE_BITS_PUISSANCE = 1_000_000


def verifier_decimal(x: float) -> float:
    if math.isinf(x) or math.isnan(x):
        raise ErreurValeur("résultat décimal hors limites (nombre trop grand)")
    return x


def _erreur_operandes(op, a, b):
    conseil = None
    if op == "+" and (type(a) is str) != (type(b) is str):
        autre = b if type(a) is str else a
        if est_nombre(autre) or type(autre) is bool or autre is None:
            conseil = "convertissez la valeur en texte avec texte(...)"
    return ErreurType(
        f"impossible d'utiliser {op} entre {decrire_type(a)} et "
        f"{decrire_type(b)}", conseil=conseil)


def binaire(op: str, a, b):
    if op == "==":
        return egal(a, b)
    if op == "!=":
        return not egal(a, b)
    if op in ("<", "<=", ">", ">="):
        return comparer(op, a, b)

    if op == "+":
        if type(a) is str and type(b) is str:
            return a + b
        if type(a) is list and type(b) is list:
            return a + b
    if not (est_nombre(a) and est_nombre(b)):
        raise _erreur_operandes(op, a, b)

    try:
        if op == "+":
            r = a + b
        elif op == "-":
            r = a - b
        elif op == "*":
            r = a * b
        elif op == "/":
            if b == 0:
                raise ErreurDivisionParZero("division par zéro")
            r = a / b
        elif op == "%":
            if b == 0:
                raise ErreurDivisionParZero("modulo par zéro")
            r = a % b
        elif op == "^":
            return puissance(a, b)
        else:  # pragma: no cover - bogue interne
            raise AssertionError(op)
    except OverflowError:
        raise ErreurValeur("résultat décimal hors limites (nombre trop grand)") from None
    if type(r) is float:
        verifier_decimal(r)
    return r


def puissance(a, b):
    if type(a) is int and type(b) is int:
        if b >= 0:
            if abs(a) > 1 and b * a.bit_length() > LIMITE_BITS_PUISSANCE:
                raise ErreurValeur("résultat de la puissance trop grand")
            return a ** b
        if a == 0:
            raise ErreurDivisionParZero(
                "zéro ne peut pas être élevé à une puissance négative")
        try:
            return verifier_decimal(float(a ** b))
        except OverflowError:
            raise ErreurValeur("résultat décimal hors limites") from None
    try:
        return verifier_decimal(math.pow(a, b))
    except OverflowError:
        raise ErreurValeur("résultat décimal hors limites") from None
    except ValueError:
        if a == 0:
            raise ErreurDivisionParZero(
                "zéro ne peut pas être élevé à une puissance négative") from None
        raise ErreurValeur(
            "puissance impossible dans les nombres réels "
            "(nombre négatif élevé à une puissance non entière)") from None


def comparer(op, a, b) -> bool:
    if not ((est_nombre(a) and est_nombre(b))
            or (type(a) is str and type(b) is str)):
        raise ErreurType(
            f"impossible de comparer {decrire_type(a)} et {decrire_type(b)} "
            f"avec {op}",
            conseil="seuls deux nombres ou deux textes peuvent être comparés "
                    "avec <, <=, >, >=")
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    return a >= b


def unaire(op: str, v):
    if not est_nombre(v):
        raise ErreurType(f"impossible d'utiliser {op} devant {decrire_type(v)}")
    return -v if op == "-" else v


def _verifier_indice(objet, indice):
    if type(objet) not in (list, str):
        raise ErreurType(
            f"les crochets [ ] s'utilisent sur une liste ou un texte, "
            f"pas sur {decrire_type(objet)}")
    if type(indice) is not int:
        raise ErreurType(f"un indice doit être un entier, pas {decrire_type(indice)}")
    taille = len(objet)
    if indice < 0 or indice >= taille:
        quoi = "la liste" if type(objet) is list else "le texte"
        if taille == 0:
            conseil = f"{quoi} est vide"
        else:
            conseil = f"les indices valides vont de 0 à {taille - 1}"
        unite = "élément" if type(objet) is list else "caractère"
        raise ErreurIndex(
            f"l'indice {indice} est hors limites : {quoi} contient "
            f"{taille} {unite}{'s' if taille > 1 else ''}", conseil=conseil)


def lire_indice(objet, indice):
    _verifier_indice(objet, indice)
    return objet[indice]


def ecrire_indice(objet, indice, valeur):
    if type(objet) is str:
        raise ErreurType("un texte ne peut pas être modifié",
                         conseil="construisez un nouveau texte, par exemple avec +")
    _verifier_indice(objet, indice)
    objet[indice] = valeur

fichiers.kplus/parser.py:
"""Analyse syntaxique : transforme la liste de jetons en arbre (AST).

Technique : « descente récursive ». Chaque règle de la grammaire
(docs/specification/grammaire.ebnf) correspond à une méthode de cette classe.
"""

from . import ast
from .erreurs import ErreurSyntaxe
from .jetons import (
    DECIMAL, ENTIER, FIN_FICHIER, IDENT, MOTCLE, NL, OPERATEURS_COMPARAISON,
    SYMBOLE, TEXTE, Jeton,
)


class Parser:
    def __init__(self, jetons: list[Jeton]):
        self.jetons = jetons
        self.i = 0

    # --- outils -------------------------------------------------------------

    @property
    def courant(self) -> Jeton:
        return self.jetons[self.i]

    def avancer(self) -> Jeton:
        jeton = self.jetons[self.i]
        if jeton.type != FIN_FICHIER:
            self.i += 1
        return jeton

    def est_motcle(self, *mots) -> bool:
        return self.courant.type == MOTCLE and self.courant.valeur in mots

    def est_symbole(self, *symboles) -> bool:
        return self.courant.type == SYMBOLE and self.courant.valeur in symboles

    def est_fin_ligne(self) -> bool:
        return self.courant.type in (NL, FIN_FICHIER)

    def erreur(self, message, jeton=None, conseil=None, incomplet=None):
        jeton = jeton or self.courant
        if incomplet is None:
            incomplet = jeton.type == FIN_FICHIER
        return ErreurSyntaxe(message, jeton.ligne, jeton.colonne, conseil,
                             incomplet)

    def sauter_fins_ligne(self):
        while self.courant.type == NL:
            self.avancer()

    def attendre_motcle(self, mot, message, conseil=None) -> Jeton:
        if not self.est_motcle(mot):
            if self.est_symbole("=") and mot in ("alors", "faire"):
                conseil = ("« = » sert à donner une valeur ; "
                           "pour comparer, écrivez ==")
            raise self.erreur(
                f"{message}, mais {self.courant.decrire()} a été trouvé",
                conseil=conseil)
        return self.avancer()

    def attendre_symbole(self, symbole, message, ouvrant=None) -> Jeton:
        if not self.est_symbole(symbole):
            if self.courant.type == FIN_FICHIER and ouvrant is not None:
                raise self.erreur(
                    f"« {ouvrant.valeur} » ouvert ici n'est jamais fermé par "
                    f"« {symbole} »", jeton=ouvrant, incomplet=True)
            raise self.erreur(
                f"{message}, mais {self.courant.decrire()} a été trouvé")
        return self.avancer()

    def attendre_fin_ligne_apres(self, mot):
        """Après « alors », « faire », etc., le bloc commence à la ligne suivante."""
        if self.courant.type == NL:
            self.avancer()
            return
        if self.courant.type == FIN_FICHIER:
            raise self.erreur(f"bloc attendu après « {mot} »", incomplet=True)
        raise self.erreur(
            f"fin de ligne attendue après « {mot} », mais "
            f"{self.courant.decrire()} a été trouvé",
            conseil="le contenu du bloc commence à la ligne suivante")

    def fin_instruction(self):
        if self.courant.type == NL:
            self.avancer()
        elif self.courant.type != FIN_FICHIER:
            raise self.erreur(
                f"fin de ligne attendue après l'instruction, mais "
                f"{self.courant.decrire()} a été trouvé",
                conseil="écrivez une seule instruction par ligne")

    def nom_declare(self, role) -> Jeton:
        jeton = self.courant
        if jeton.type == IDENT:
            return self.avancer()
        if jeton.type == MOTCLE:
            raise self.erreur(
                f"« {jeton.valeur} » est un mot réservé de K+ et ne peut pas "
                f"servir de {role}", conseil="choisissez un autre nom")
        raise self.erreur(f"{role} attendu, mais {jeton.decrire()} a été trouvé")

    # --- programme et blocs -----------------------------------------------------

    def programme(self) -> ast.Programme:
        instructions = []
        self.sauter_fins_ligne()
        while self.courant.type != FIN_FICHIER:
            instructions.append(self.instruction())
            self.fin_instruction()
            self.sauter_fins_ligne()
        return ast.Programme(1, 1, instructions)

    def bloc(self, fermants, ouvrant: Jeton, nom_bloc: str) -> list:
        """Lit des instructions jusqu'à l'un des mots-clés « fermants »."""
        instructions = []
        self.sauter_fins_ligne()
        while not self.est_motcle(*fermants):
            if self.courant.type == FIN_FICHIER:
                raise ErreurSyntaxe(
                    f"le bloc « {nom_bloc} » ouvert ici n'est jamais fermé "
                    f"par « fin »", ouvrant.ligne, ouvrant.colonne,
                    incomplet=True)
            instructions.append(self.instruction())
            self.fin_instruction()
            self.sauter_fins_ligne()
        return instructions

    # --- instructions -------------------------------------------------------------

    def instruction(self):
        jeton = self.courant
        if jeton.type == MOTCLE:
            mot = jeton.valeur
            if mot in ("variable", "constante"):
                return self.declaration()
            if mot == "si":
                return self.si()
            if mot == "tant":
                return self.tant_que()
            if mot == "pour":
                return self.pour()
            if mot == "fonction":
                return self.fonction()
            if mot == "essayer":
                return self.essayer()
            if mot == "retourner":
                self.avancer()
                valeur = None if self.est_fin_ligne() else self.expression()
                return ast.Retourner(jeton.ligne, jeton.colonne, valeur)
            if mot == "arreter":
                self.avancer()
                return ast.Arreter(jeton.ligne, jeton.colonne)
            if mot == "continuer":
                self.avancer()
                return ast.Continuer(jeton.ligne, jeton.colonne)
            if mot == "lever":
                self.avancer()
                return ast.Lever(jeton.ligne, jeton.colonne, self.expression())
            if mot == "fin":
                raise self.erreur("« fin » inattendu : aucun bloc n'est ouvert ici")
            if mot == "sinon":
                raise self.erreur(
                    "« sinon » inattendu : il doit suivre le bloc d'un « si »")
            if mot == "attraper":
                raise self.erreur(
                    "« attraper » inattendu : il doit suivre un bloc « essayer »")

        debut = self.courant
        expression = self.expression()
        if self.est_symbole("="):
            egal = self.avancer()
            if not self.est_cible(expression):
                raise self.erreur(
                    "on ne peut donner une valeur qu'à une variable ou à un "
                    "élément de liste", jeton=egal,
                    conseil="pour comparer deux valeurs, écrivez ==")
            valeur = self.expression()
            return ast.Affectation(debut.ligne, debut.colonne, expression,
                                   valeur)
        return ast.InstructionExpression(debut.ligne, debut.colonne, expression)

    def est_cible(self, noeud) -> bool:
        if isinstance(noeud, ast.Nom):
            return True
        if isinstance(noeud, ast.AccesIndice):
            return self.est_cible(noeud.objet)
        return False

    def declaration(self):
        mot = self.avancer()
        constante = mot.valeur == "constante"
        role = "nom de constante" if constante else "nom de variable"
        nom = self.nom_declare(role)
        if not self.est_symbole("="):
            raise self.erreur(
                f"« = » attendu après « {nom.valeur} » : une {mot.valeur} "
                f"doit recevoir une valeur",
                conseil=f"exemple : {mot.valeur} {nom.valeur} = nul")
        self.avancer()
        valeur = self.expression()
        return ast.Declaration(mot.ligne, mot.colonne, nom.valeur, valeur,
                               constante)

    def si(self):
        jeton_si = self.avancer()
        branches = []
        condition = self.expression()
        self.attendre_motcle("alors", "« alors » attendu après la condition")
        self.attendre_fin_ligne_apres("alors")
        corps = self.bloc(("fin", "sinon"), jeton_si, "si")
        branches.append((condition, corps))
        sinon = None
        while self.est_motcle("sinon"):
            jeton_sinon = self.avancer()
            if self.est_motcle("si"):
                self.avancer()
                condition = self.expression()
                self.attendre_motcle("alors", "« alors » attendu après la condition")
                self.attendre_fin_ligne_apres("alors")
                corps = self.bloc(("fin", "sinon"), jeton_si, "si")
                branches.append((condition, corps))
            else:
                self.attendre_fin_ligne_apres("sinon")
                sinon = self.bloc(("fin", "sinon"), jeton_si, "si")
                if self.est_motcle("sinon"):
                    raise self.erreur(
                        "un seul « sinon » est permis, et il doit être le dernier",
                        conseil="pour une autre condition, écrivez « sinon si ... alors » "
                                "avant le « sinon » final")
                break
        self.avancer()  # fin
        return ast.Si(jeton_si.ligne, jeton_si.colonne, branches, sinon)

    def tant_que(self):
        jeton = self.avancer()
        self.attendre_motcle("que", "« que » attendu après « tant »",
                             conseil="écrivez : tant que condition faire")
        condition = self.expression()
        self.attendre_motcle("faire", "« faire » attendu après la condition")
        self.attendre_fin_ligne_apres("faire")
        corps = self.bloc(("fin",), jeton, "tant que")
        self.avancer()
        return ast.TantQue(jeton.ligne, jeton.colonne, condition, corps)

    def pour(self):
        jeton = self.avancer()
        if self.est_motcle("chaque"):
            self.avancer()
            variable = self.nom_declare("nom de variable")
            self.attendre_motcle("dans", "« dans » attendu après le nom de la variable",
                                 conseil="écrivez : pour chaque x dans liste faire")
            iterable = self.expression()
            self.attendre_motcle("faire", "« faire » attendu")
            self.attendre_fin_ligne_apres("faire")
            corps = self.bloc(("fin",), jeton, "pour chaque")
            self.avancer()
            return ast.PourChaque(jeton.ligne, jeton.colonne, variable.valeur,
                                  iterable, corps)

        variable = self.nom_declare("nom de variable")
        self.attendre_motcle("de", "« de » attendu après le nom de la variable",
                             conseil="écrivez : pour i de 1 à 10 faire")
        debut = self.expression()
        conseil = None
        if self.courant.type == IDENT and self.courant.valeur in ("a", "A"):
            conseil = "écrivez « à » avec un accent : pour i de 1 à 10 faire"
        self.attendre_motcle("à", "« à » attendu après la valeur de départ",
                             conseil=conseil)
        fin = self.expression()
        pas = None
        if self.est_motcle("pas"):
            self.avancer()
            pas = self.expression()
        self.attendre_motcle("faire", "« faire » attendu")
        self.attendre_fin_ligne_apres("faire")
        corps = self.bloc(("fin",), jeton, "pour")
        self.avancer()
        return ast.Pour(jeton.ligne, jeton.colonne, variable.valeur, debut,
                        fin, pas, corps)

    def fonction(self):
        jeton = self.avancer()
        nom = self.nom_declare("nom de fonction")
        ouvrant = self.attendre_symbole(
            "(", f"« ( » attendu après le nom de la fonction « {nom.valeur} »")
        parametres = []
        if not self.est_symbole(")"):
            while True:
                parametre = self.nom_declare("nom de paramètre")
                if parametre.valeur in parametres:
                    raise self.erreur(
                        f"le paramètre « {parametre.valeur} » apparaît deux fois",
                        jeton=parametre)
                parametres.append(parametre.valeur)
                if not self.est_symbole(","):
                    break
                self.avancer()
        self.attendre_symbole(")", "« ) » ou « , » attendu dans la liste des "
                              "paramètres", ouvrant)
        self.attendre_fin_ligne_apres(")")
        corps = self.bloc(("fin",), jeton, "fonction")
        self.avancer()
        return ast.DefinitionFonction(jeton.ligne, jeton.colonne, nom.valeur,
                                      parametres, corps)

    def essayer(self):
        jeton = self.avancer()
        self.attendre_fin_ligne_apres("essayer")
        corps = self.bloc(("attraper", "fin"), jeton, "essayer")
        if self.est_motcle("fin"):
            raise self.erreur(
                "« attraper » attendu avant « fin » : un bloc « essayer » "
                "doit avoir une partie « attraper »")
        self.avancer()  # attraper
        nom_erreur = None
        if not self.est_fin_ligne():
            nom_erreur = self.nom_declare("nom de variable").valeur
        self.attendre_fin_ligne_apres("attraper")
        gestionnaire = self.bloc(("fin",), jeton, "essayer")
        self.avancer()
        return ast.Essayer(jeton.ligne, jeton.colonne, corps, nom_erreur,
                           gestionnaire)

    # --- expressions --------------------------------------------------------------

    def expression(self):
        return self.ou()

    def ou(self):
        gauche = self.et()
        while self.est_motcle("ou"):
            op = self.avancer()
            gauche = ast.OperationLogique(op.ligne, op.colonne, "ou", gauche,
                                          self.et())
        return gauche

    def et(self):
        gauche = self.non()
        while self.est_motcle("et"):
            op = self.avancer()
            gauche = ast.OperationLogique(op.ligne, op.colonne, "et", gauche,
                                          self.non())
        return gauche

    def non(self):
        if self.est_motcle("non"):
            op = self.avancer()
            return ast.OperationUnaire(op.ligne, op.colonne, "non", self.non())
        return self.comparaison()

    def comparaison(self):
        gauche = self.addition()
        if self.est_symbole(*OPERATEURS_COMPARAISON):
            op = self.avancer()
            gauche = ast.OperationBinaire(op.ligne, op.colonne, op.valeur,
                                          gauche, self.addition())
            if self.est_symbole(*OPERATEURS_COMPARAISON):
                raise self.erreur(
                    "les comparaisons ne peuvent pas s'enchaîner",
                    conseil="écrivez par exemple : a < b et b < c")
        return gauche

    def addition(self):
        gauche = self.multiplication()
        while self.est_symbole("+", "-"):
            op = self.avancer()
            gauche = ast.OperationBinaire(op.ligne, op.colonne, op.valeur,
                                          gauche, self.multiplication())
        return gauche

    def multiplication(self):
        gauche = self.unaire()
        while self.est_symbole("*", "/", "%"):
            op = self.avancer()
            gauche = ast.OperationBinaire(op.ligne, op.colonne, op.valeur,
                                          gauche, self.unaire())
        return gauche

    def unaire(self):
        if self.est_symbole("-", "+"):
            op = self.avancer()
            return ast.OperationUnaire(op.ligne, op.colonne, op.valeur,
                                       self.unaire())
        return self.puissance()

    def puissance(self):
        base = self.postfixe()
        if self.est_symbole("^"):
            op = self.avancer()
            # unaire() rappelle puissance() : associativité à droite.
            return ast.OperationBinaire(op.ligne, op.colonne, "^", base,
                                        self.unaire())
        return base

    def postfixe(self):
        expression = self.primaire()
        while True:
            if self.est_symbole("("):
                ouvrant = self.avancer()
                arguments = []
                if not self.est_symbole(")"):
                    arguments.append(self.expression())
                    while self.est_symbole(","):
                        self.avancer()
                        arguments.append(self.expression())
                self.attendre_symbole(
                    ")", "« ) » ou « , » attendu dans les arguments", ouvrant)
                expression = ast.Appel(expression.ligne, expression.colonne,
                                       expression, arguments)
            elif self.est_symbole("["):
                ouvrant = self.avancer()
                indice = self.expression()
                self.attendre_symbole("]", "« ] » attendu après l'indice", ouvrant)
                expression = ast.AccesIndice(ouvrant.ligne, ouvrant.colonne,
                                             expression, indice)
            else:
                return expression

    def primaire(self):
        jeton = self.courant
        if jeton.type in (ENTIER, DECIMAL, TEXTE):
            self.avancer()
            return ast.Litteral(jeton.ligne, jeton.colonne, jeton.valeur)
        if jeton.type == MOTCLE and jeton.valeur in ("vrai", "faux", "nul"):
            self.avancer()
            valeur = {"vrai": True, "faux": False, "nul": None}[jeton.valeur]
            return ast.Litteral(jeton.ligne, jeton.colonne, valeur)
        if jeton.type == IDENT:
            self.avancer()
            return ast.Nom(jeton.ligne, jeton.colonne, jeton.valeur)
        if self.est_symbole("("):
            ouvrant = self.avancer()
            expression = self.expression()
            self.attendre_symbole(")", "« ) » attendu", ouvrant)
            return expression
        if self.est_symbole("["):
            ouvrant = self.avancer()
            elements = []
            while not self.est_symbole("]"):
                elements.append(self.expression())
                if not self.est_symbole(","):
                    break
                self.avancer()
            self.attendre_symbole("]", "« ] » ou « , » attendu dans la liste",
                                  ouvrant)
            return ast.ListeLitterale(ouvrant.ligne, ouvrant.colonne, elements)

        conseil = None
        if jeton.type == MOTCLE:
            conseil = f"« {jeton.valeur} » est un mot réservé de K+"
        raise self.erreur(
            f"expression attendue, mais {jeton.decrire()} a été trouvé",
            conseil=conseil)


def analyser_syntaxe(jetons: list[Jeton]) -> ast.Programme:
    return Parser(jetons).programme()

fichiers.kplus/valeurs.py:
"""Valeurs de K+ et leur représentation.

Correspondance entre les types K+ et Python :
    entier   -> int        décimal  -> float     texte -> str
    booléen  -> bool       nul      -> None      liste -> list
    fonction -> FonctionUtilisateur ou FonctionNative

Attention : en Python, bool est un sous-type de int. On teste donc toujours
« type(v) is int » et jamais « isinstance(v, int) ».
"""


class FonctionUtilisateur:
    """Fonction écrite en K+ avec « fonction ... fin »."""

    __slots__ = ("nom", "parametres", "corps", "fermeture")

    def __init__(self, nom, parametres, corps, fermeture):
        self.nom = nom
        self.parametres = parametres
        self.corps = corps
        self.fermeture = fermeture      # environnement de définition


class FonctionNative:
    """Fonction fournie par K+ (afficher, longueur, ...)."""

    __slots__ = ("nom", "arite_min", "arite_max", "implementation")

    def __init__(self, nom, arite_min, arite_max, implementation):
        self.nom = nom
        self.arite_min = arite_min
        self.arite_max = arite_max      # None = pas de limite
        self.implementation = implementation


def est_nombre(v) -> bool:
    return type(v) is int or type(v) is float


def est_fonction(v) -> bool:
    return isinstance(v, (FonctionUtilisateur, FonctionNative))


def nom_type(v) -> str:
    t = type(v)
    if t is bool:
        return "booléen"
    if t is int:
        return "entier"
    if t is float:
        return "décimal"
    if t is str:
        return "texte"
    if v is None:
        return "nul"
    if t is list:
        return "liste"
    if est_fonction(v):
        return "fonction"
    raise TypeError(f"valeur Python inattendue : {v!r}")  # bogue interne


ARTICLES = {
    "booléen": "un booléen", "entier": "un entier", "décimal": "un décimal",
    "texte": "un texte", "nul": "nul", "liste": "une liste",
    "fonction": "une fonction",
}


def decrire_type(v) -> str:
    """« un entier », « une liste », ... pour les messages d'erreur."""
    return ARTICLES[nom_type(v)]


def _texte_entre_guillemets(t: str) -> str:
    t = (t.replace("\\", "\\\\").replace('"', '\\"')
         .replace("\n", "\\n").replace("\t", "\\t"))
    return f'"{t}"'


def representer(v, imbrique: bool = False, _en_cours=None) -> str:
    """Représentation textuelle d'une valeur (spécification §4.2).

    imbrique=True : la valeur est dans une liste, les textes sont alors
    affichés entre guillemets.
    """
    t = type(v)
    if t is bool:
        return "vrai" if v else "faux"
    if v is None:
        return "nul"
    if t is int:
        return str(v)
    if t is float:
        return repr(v)
    if t is str:
        return _texte_entre_guillemets(v) if imbrique else v
    if t is list:
        en_cours = _en_cours if _en_cours is not None else set()
        if id(v) in en_cours:
            return "[...]"                  # liste qui se contient elle-même
        en_cours.add(id(v))
        try:
            # Boucle simple (pas de générateur) : la récursion reste
            # entièrement en Python, ce qui la rend sûre aussi dans Pyodide.
            morceaux = []
            for element in v:
                morceaux.append(representer(element, True, en_cours))
            return "[" + ", ".join(morceaux) + "]"
        finally:
            en_cours.discard(id(v))
    if est_fonction(v):
        return f"<fonction {v.nom}>"
    raise TypeError(f"valeur Python inattendue : {v!r}")  # bogue interne


def egal(a, b) -> bool:
    """Égalité K+ (opérateur ==) : ne provoque jamais d'erreur."""
    if est_nombre(a) and est_nombre(b):
        return a == b
    if type(a) is not type(b):
        return False
    if type(a) is list:
        if a is b:
            return True
        if len(a) != len(b):
            return False
        for i in range(len(a)):           # boucle simple : voir representer()
            if not egal(a[i], b[i]):
                return False
        return True
    if est_fonction(a):
        return a is b
    return a == b

